<?php
// Temporarily paused; set to true when the college resumes this module.
function rtEnabled():bool{return false;}
function rtAllowed(?array $u):bool{return rtEnabled()&&$u&&!empty($u['active'])&&in_array($u['role'],['admin','exam','daa'],true);}
function rtAssert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function rtReady():bool{try{q('SELECT id FROM result_settings LIMIT 1');return true;}catch(PDOException $e){return false;}}
function rtDefaults():array{return ['dean'=>'','president'=>'','heading'=>'Academic Transcript','dz_university'=>'༄༅། འབྲུག་རྒྱལ་འཛིན་གཙུག་ལག་སློབ་སྡེ།','dz_college'=>'༄༅། རང་བྱུང་ཐོན་ཁུངས་མཐོ་རིམ་སློབ་གྲྭ།','rub_logo'=>'assets/results/rub.jpg','cnr_logo'=>'assets/results/cnr.png'];}
function rtSettings():array{return json_decode(one('SELECT payload FROM result_settings WHERE id=1')['payload'],true)+rtDefaults();}
function rtText(array $p,string $key,int $max=190):string{$v=is_scalar($p[$key]??null)?trim((string)$p[$key]):'';rtAssert($v!==''&&mb_strlen($v)<=$max,'Enter '.$key.' (up to '.$max.' characters).');return $v;}
function rtAudit(array $u,int $id,string $action,array $details):void{q('INSERT INTO result_audit(cohort_id,actor_id,action,details,created_at) VALUES(?,?,?,?,?)',[$id,$u['id'],$action,json_encode($details,JSON_THROW_ON_ERROR),now()]);}
function rtCohort(int $id,bool $lock=false):array{$c=one('SELECT * FROM result_cohorts WHERE id=?'.($lock&&db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id]);rtAssert((bool)$c,'Result batch not found.');return $c;}
function rtWeights(int $duration):array{return match($duration){2=>[30,70],3=>[20,30,50],4=>[10,20,30,40],default=>throw new RuntimeException('Choose a 2, 3 or 4 year programme.')};}
function rtHeaders():array{return ['Student Number','Student Name','Semester','Module Code','Module Title','Year of Passing','Maximum Mark','Mark Secured','Credit'];}
function rtRead(array $file):array{
 rtAssert(($file['error']??1)===UPLOAD_ERR_OK&&$file['size']<=10*1024*1024&&is_uploaded_file($file['tmp_name']),'Upload a CSV or XLSX file up to 10 MB.');$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));
 if($ext==='csv'){$f=fopen($file['tmp_name'],'r');$rows=[];while(($row=fgetcsv($f))!==false){$rows[]=$row;rtAssert(count($rows)<=20001,'Split the upload into files of at most 20,000 rows.');}fclose($f);return $rows;}
 rtAssert($ext==='xlsx','Use CSV or XLSX. Download the portal template; the old formatted certificate workbook is a design reference.');
 $z=new ZipArchive();rtAssert($z->open($file['tmp_name'])===true,'Invalid XLSX.');$size=0;for($i=0;$i<$z->numFiles;$i++)$size+=$z->statIndex($i)['size'];$z->close();rtAssert($size<40*1024*1024,'Expanded workbook is too large.');
 $reader=new \PhpOffice\PhpSpreadsheet\Reader\Xlsx();$reader->setReadDataOnly(true);$book=$reader->load($file['tmp_name']);$sheet=$book->getSheet(0);rtAssert($sheet->getHighestDataRow()<=20001&&\PhpOffice\PhpSpreadsheet\Cell\Coordinate::columnIndexFromString($sheet->getHighestDataColumn())<=20,'Use the nine-column template, with at most 20,000 rows.');
 foreach($sheet->getRowIterator() as $row)foreach($row->getCellIterator()as $cell)rtAssert($cell->getDataType()!=='f','Upload values, not Excel formulas.');$rows=$sheet->toArray(null,false,false,false);$book->disconnectWorksheets();return $rows;
}
function rtParse(array $rows,int $duration):array{
 $header=array_map(fn($x)=>trim(ltrim((string)$x,"\xEF\xBB\xBF")),array_shift($rows)??[]);rtAssert(count($header)===9&&count(array_unique($header))===9&&!array_diff(rtHeaders(),$header),'Use the nine column headings from the results template.');$result=[];$errors=[];$keys=[];
 foreach($rows as $i=>$raw){if(!array_filter($raw,fn($x)=>trim((string)$x)!==''))continue;try{
  rtAssert(count($raw)===9,'Expected nine columns.');$p=array_combine($header,$raw);$r=[];foreach(['Student Number'=>['student_number',60],'Student Name'=>['student_name',160],'Module Code'=>['module_code',40],'Module Title'=>['module_title',190]]as $key=>[$field,$max]){$r[$field]=rtText($p,$key,$max);rtAssert(!preg_match('/^[=+@\t\r]/u',$r[$field]),'Text must not start with a spreadsheet formula character.');}
  $r['module_code']=strtoupper($r['module_code']);foreach(['Semester'=>['semester',1,$duration*2],'Year of Passing'=>['passing_year',1950,2200],'Maximum Mark'=>['maximum',0.01,1000],'Mark Secured'=>['mark',0,1000],'Credit'=>['credits',0.01,200]]as $key=>[$field,$min,$max]){rtAssert(is_numeric($p[$key])&&is_finite((float)$p[$key])&&(float)$p[$key]>=$min&&(float)$p[$key]<=$max,'Invalid '.$key.'.');$r[$field]=(float)$p[$key];rtAssert(abs($r[$field]-round($r[$field],4))<0.00000001,'Use at most four decimal places for '.$key.'.');}
  rtAssert(floor($r['semester'])===$r['semester']&&floor($r['passing_year'])===$r['passing_year'],'Semester and passing year must be whole numbers.');$r['semester']=(int)$r['semester'];$r['passing_year']=(int)$r['passing_year'];rtAssert($r['mark']<=$r['maximum'],'Mark exceeds maximum.');$key=$r['student_number'].'|'.$r['semester'].'|'.$r['module_code'];rtAssert(!isset($keys[$key]),'Duplicate student/module/semester in this file.');$keys[$key]=true;$result[]=$r;
 }catch(Throwable $e){$errors[]='Row '.($i+2).': '.$e->getMessage();}}
 rtAssert(!$errors,implode("\n",array_slice($errors,0,30)).(count($errors)>30?'\nMore errors exist; fix these and revalidate.':''));rtAssert((bool)$result,'No marks found.');return $result;
}
function rtKey(array $r):string{return $r['student_number'].'|'.$r['semester'].'|'.$r['module_code'];}
function rtMerge(array $old,array $incoming,bool $replace):array{
 $map=[];foreach($old as $r)$map[rtKey($r)]=$r;$changed=0;$same=0;
 foreach($incoming as $r){$key=rtKey($r);$prev=$map[$key]??null;if($prev){$equal=true;foreach($r as $k=>$v){$numeric=in_array($k,['semester','passing_year','maximum','mark','credits'],true);if($numeric?(float)$prev[$k] !== (float)$v:(string)$prev[$k] !== (string)$v)$equal=false;}if($equal){$same++;continue;}rtAssert($replace,'Conflicting saved mark for '.$r['student_number'].' / '.$r['module_code'].'. Select correction mode and give a reason.');}$map[$key]=$r;$changed++;}
 $names=[];$modules=[];foreach($map as $r){$sid=$r['student_number'];rtAssert(!isset($names[$sid])||$names[$sid]===$r['student_name'],'Conflicting names for student '.$sid.'.');$names[$sid]=$r['student_name'];$key=$r['semester'].'|'.$r['module_code'];$spec=[$r['module_title'],(float)$r['maximum'],(float)$r['credits']];rtAssert(!isset($modules[$key])||$modules[$key]===$spec,'Inconsistent module title, maximum or credit for '.$r['module_code'].'.');$modules[$key]=$spec;}
 return ['rows'=>array_values($map),'changed'=>$changed,'same'=>$same];
}
function rtReport(array $c,array $rows):array{
 $expected=[];$students=[];$weights=rtWeights((int)$c['duration']);foreach($rows as $r){$key=$r['semester'].'|'.$r['module_code'];$expected[$key]=true;$sid=$r['student_number'];$students[$sid]['name']=$r['student_name'];$students[$sid]['rows'][]=$r;}
 foreach($students as $sid=>&$s){usort($s['rows'],fn($a,$b)=>[$a['semester'],$a['module_code']]<=>[$b['semester'],$b['module_code']]);$s['numerator']=0;$s['denominator']=0;$s['years']=[];$seen=[];$semesters=[];
 foreach($s['rows']as $r){$y=(int)ceil($r['semester']/2);$w=$weights[$y-1]/100;$points=(float)$r['mark']*(float)$r['credits'];$max=(float)$r['maximum']*(float)$r['credits'];$s['numerator']+=$points*$w;$s['denominator']+=$max*$w;$s['years'][$y]=($s['years'][$y]??0)+$points*$w;$seen[$r['semester'].'|'.$r['module_code']]=true;$semesters[(int)$r['semester']]=true;}
 $s['missing']=count(array_diff_key($expected,$seen));$s['missing_semesters']=array_values(array_diff(range(1,(int)$c['duration']*2),array_keys($semesters)));$s['complete']=!$s['missing']&&!$s['missing_semesters'];$s['percent']=$s['denominator']>0?100*$s['numerator']/$s['denominator']:0;$p=$s['percent'];$s['performance']=$p>=80?'Outstanding':($p>=70?'Very Good':($p>=60?'Good':($p>=50?'Satisfactory':'Fail')));
 }unset($s);uksort($students,'strnatcmp');return $students;
}
function rtPost(?array $u,string $action,array $p):int{
 rtAssert(rtAllowed($u),'Exam Cell, DAA or Admin access required.');rtAssert(rtReady(),'Run the results migration first.');$id=(int)($p['cohort_id']??0);
 if($action==='rt_preview'){unset($_SESSION['rt_preview']);$c=rtCohort($id);rtAssert($c['status']==='Draft','Reopen the batch before changing marks.');$rows=rtParse(rtRead($_FILES['marks']??[]),(int)$c['duration']);$replace=($p['correction']??'')==='1';$reason=$replace?rtText($p,'reason',1000):'Semester upload';$merged=rtMerge(all('SELECT * FROM result_marks WHERE cohort_id=?',[$id]),$rows,$replace);$_SESSION['rt_preview']=['id'=>$id,'revision'=>$c['revision'],'rows'=>$rows,'replace'=>$replace,'reason'=>$reason,'changed'=>$merged['changed'],'same'=>$merged['same'],'at'=>time(),'user'=>$u['id']];return $id;}
 db()->beginTransaction();$written=[];try{
 if($action==='rt_settings'){$s=rtSettings();foreach(['dean','president','heading','dz_university','dz_college']as $k)$s[$k]=rtText($p,$k,190);
 foreach(['rub_logo','cnr_logo']as $k){$f=$_FILES[$k]??[];if(($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;rtAssert(($f['error']??1)===UPLOAD_ERR_OK&&$f['size']<=2*1024*1024&&is_uploaded_file($f['tmp_name']),'Logo must be PNG or JPEG up to 2 MB.');$info=getimagesize($f['tmp_name']);rtAssert($info&&in_array($info[2],[IMAGETYPE_PNG,IMAGETYPE_JPEG],true)&&$info[0]*$info[1]<=20000000,'Use a PNG or JPEG logo up to 20 megapixels.');$dir=__DIR__.'/../../storage/result-logos';if(!is_dir($dir))rtAssert(mkdir($dir,0700,true),'Unable to create logo storage.');$key=bin2hex(random_bytes(20)).($info[2]===IMAGETYPE_PNG?'.png':'.jpg');rtAssert(move_uploaded_file($f['tmp_name'],$dir.'/'.$key),'Logo upload failed.');chmod($dir.'/'.$key,0600);$written[]=$dir.'/'.$key;$s[$k]=$key;}
 $old=rtSettings();q('UPDATE result_settings SET payload=? WHERE id=1',[json_encode($s,JSON_THROW_ON_ERROR)]);rtAudit($u,0,'Print settings updated',['before'=>$old,'after'=>$s]);$id=0;
 }elseif($action==='rt_create'){$duration=(int)($p['duration']??0);rtWeights($duration);rtAssert(dateValid($p['issued_on']??''),'Enter a valid issue date.');$s=rtSettings();rtAssert($s['dean']!==''&&$s['president']!=='','Save the Dean and President names in Print settings first.');q('INSERT INTO result_cohorts(title,programme,duration,study_period,issued_on,settings,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)',[rtText($p,'title'),rtText($p,'programme'),$duration,rtText($p,'study_period'),$p['issued_on'],json_encode($s,JSON_THROW_ON_ERROR),$u['id'],now()]);$id=(int)db()->lastInsertId();rtAudit($u,$id,'Batch created',[]);
 }else{$c=rtCohort($id,true);$rows=all('SELECT * FROM result_marks WHERE cohort_id=?',[$id]);
 if($action==='rt_commit'){$v=$_SESSION['rt_preview']??[];rtAssert(($v['id']??0)===$id&&($v['user']??0)===$u['id']&&($v['at']??0)>time()-1800,'Preview expired. Upload again.');rtAssert((int)$v['revision']===(int)$c['revision']&&$c['status']==='Draft','Batch changed. Validate again.');rtAssert(($p['confirmed']??'')==='1','Confirm the upload preview.');rtMerge($rows,$v['rows'],$v['replace']);
 foreach($v['rows']as $r){$old=one('SELECT * FROM result_marks WHERE cohort_id=? AND student_number=? AND semester=? AND module_code=?',[$id,$r['student_number'],$r['semester'],$r['module_code']]);if($old){q('UPDATE result_marks SET student_name=?,module_title=?,passing_year=?,maximum=?,mark=?,credits=? WHERE id=?',[$r['student_name'],$r['module_title'],$r['passing_year'],$r['maximum'],$r['mark'],$r['credits'],$old['id']]);}else q('INSERT INTO result_marks(cohort_id,student_number,student_name,semester,module_code,module_title,passing_year,maximum,mark,credits) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$r['student_number'],$r['student_name'],$r['semester'],$r['module_code'],$r['module_title'],$r['passing_year'],$r['maximum'],$r['mark'],$r['credits']]);}
 rtAudit($u,$id,'Marks imported',['reason'=>$v['reason'],'before'=>$v['replace']?$rows:[],'imported'=>$v['rows']]);q('UPDATE result_cohorts SET revision=revision+1 WHERE id=?',[$id]);unset($_SESSION['rt_preview']);
 }else{rtAssert((int)($p['revision']??0)===(int)$c['revision'],'Batch changed. Refresh before saving.');$reason=rtText($p,'reason',1000);
 if($action==='rt_finalize'){$students=rtReport($c,$rows);rtAssert($c['status']==='Draft'&&(bool)$students,'Draft marks are required.');foreach($students as $s)rtAssert($s['complete'],'Some students have missing modules or semesters.');rtAssert(($p['confirmed']??'')==='1','Confirm that the roster, modules, final marks and print preview have been checked.');q("UPDATE result_cohorts SET status='Finalized',revision=revision+1 WHERE id=?",[$id]);rtAudit($u,$id,'Batch finalized',['reason'=>$reason,'cohort'=>$c,'marks'=>$rows]);}
 elseif($action==='rt_reopen'){rtAssert($c['status']==='Finalized','Only finalized batches can be reopened.');q("UPDATE result_cohorts SET status='Draft',revision=revision+1 WHERE id=?",[$id]);rtAudit($u,$id,'Batch reopened',['reason'=>$reason]);}
 elseif($action==='rt_remove'){rtAssert($c['status']==='Draft','Reopen before removing a student.');$sid=rtText($p,'student_number',60);$before=all('SELECT * FROM result_marks WHERE cohort_id=? AND student_number=?',[$id,$sid]);rtAssert((bool)$before&&($p['confirmed']??'')==='1','Select a student and confirm removal.');q('DELETE FROM result_marks WHERE cohort_id=? AND student_number=?',[$id,$sid]);q('UPDATE result_cohorts SET revision=revision+1 WHERE id=?',[$id]);rtAudit($u,$id,'Student removed',['reason'=>$reason,'marks'=>$before]);}
 elseif($action==='rt_delete'){rtAssert(($p['confirmed']??'')==='1','Confirm deletion of this batch and all its marks.');rtAudit($u,$id,'Batch deleted',['reason'=>$reason,'cohort'=>$c,'marks'=>$rows]);q('DELETE FROM result_marks WHERE cohort_id=?',[$id]);q('DELETE FROM result_cohorts WHERE id=?',[$id]);if((int)($_SESSION['rt_preview']['id']??0)===$id)unset($_SESSION['rt_preview']);$id=0;}
 elseif($action==='rt_metadata'){rtAssert($c['status']==='Draft','Reopen before editing batch details.');rtAssert(dateValid($p['issued_on']??''),'Invalid issue date.');$settings=($p['refresh_settings']??'')==='1'?json_encode(rtSettings(),JSON_THROW_ON_ERROR):$c['settings'];q('UPDATE result_cohorts SET title=?,programme=?,study_period=?,issued_on=?,settings=?,revision=revision+1 WHERE id=?',[rtText($p,'title'),rtText($p,'programme'),rtText($p,'study_period'),$p['issued_on'],$settings,$id]);rtAudit($u,$id,'Batch details updated',['reason'=>$reason,'before'=>$c]);}
 else throw new RuntimeException('Unknown result action.');
 }}db()->commit();return $id;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();foreach($written as $f)unlink($f);throw $e;}
}
function rtLogoPath(string $logo):string{if(in_array($logo,['assets/results/rub.jpg','assets/results/cnr.png'],true))return __DIR__.'/../../public/'.$logo;rtAssert(preg_match('/^[a-f0-9]{40}\.(png|jpg)$/D',$logo)===1,'Invalid logo.');return __DIR__.'/../../storage/result-logos/'.$logo;}
function rtLogoData(string $logo):string{$path=rtLogoPath($logo);rtAssert(is_file($path),'Saved logo not available.');return 'data:'.(str_ends_with($path,'.png')?'image/png':'image/jpeg').';base64,'.base64_encode(file_get_contents($path));}
function rtCsv(?array $u):never{rtAssert(rtAllowed($u),'Access denied.');$id=(int)($_GET['cohort_id']??0);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="result-marks.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,rtHeaders());if($id){rtCohort($id);foreach(all('SELECT * FROM result_marks WHERE cohort_id=? ORDER BY student_number,semester,module_code',[$id])as $r)fputcsv($f,array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,[$r['student_number'],$r['student_name'],$r['semester'],$r['module_code'],$r['module_title'],$r['passing_year'],$r['maximum'],$r['mark'],$r['credits']]));}fclose($f);exit;}

function rtLogoUrl(string $logo):string{rtLogoPath($logo);return str_starts_with($logo,'assets/')?$logo:'?page=rt_logo&key='.rawurlencode($logo);}
function rtLogoServe(?array $u):never{rtAssert(rtAllowed($u),'Access denied.');$logo=(string)($_GET['key']??'');$path=rtLogoPath($logo);rtAssert(is_file($path),'Logo not available.');header('Content-Type: '.(str_ends_with($path,'.png')?'image/png':'image/jpeg'));readfile($path);exit;}
